/* Prism loader + Doe image-resize runtime. */
(function () {
    if (typeof document === 'undefined' && typeof importScripts === 'function') {
        importScripts('prism.core.min.js');
        return;
    }

    if (typeof document !== 'undefined' && document.readyState === 'loading') {
        document.write('<script src="prism.core.min.js"><\/script>');
    } else if (typeof document !== 'undefined' && !window.Prism) {
        const s = document.createElement('script');
        s.src = 'prism.core.min.js';
        document.head.appendChild(s);
    }

    if (typeof document === 'undefined') return;

    const style = document.createElement('style');
    style.textContent = `
        .task-detail-body .markdown-body .image-resizer-wrapper.has-custom-size {
            overflow: visible !important;
            box-sizing: border-box !important;
            max-width: 100% !important;
        }
        .task-detail-body .markdown-body .image-resizer-wrapper.has-custom-size img {
            display: block !important;
            width: 100% !important;
            height: 100% !important;
            max-width: 100% !important;
            max-height: none !important;
            object-fit: fill !important;
            box-sizing: border-box !important;
        }
        .task-detail-body .markdown-body .image-resize-handle {
            position: absolute !important;
            right: -7px !important;
            bottom: -7px !important;
            width: 16px !important;
            height: 16px !important;
            display: flex !important;
            align-items: center !important;
            justify-content: center !important;
            padding: 0 !important;
            border: 0 !important;
            background: transparent !important;
            box-shadow: none !important;
            cursor: nwse-resize !important;
            z-index: 30 !important;
            opacity: 1 !important;
        }
        .task-detail-body .markdown-body .image-resize-handle::before {
            content: '↘' !important;
            display: block !important;
            color: var(--text-secondary) !important;
            font-size: 15px !important;
            line-height: 16px !important;
            font-weight: 700 !important;
            text-shadow: 0 1px 2px rgba(0,0,0,.25) !important;
            transform: translate(1px, 1px) !important;
        }
        .task-detail-body .markdown-body .image-resize-handle::after { content: none !important; display: none !important; }
        html body:has(.image-resizer-wrapper.is-resizing),
        html body:has(.image-resizer-wrapper.is-resizing) * { cursor: nwse-resize !important; }
    `;
    document.head.appendChild(style);

    const decode = value => {
        const ta = document.createElement('textarea');
        ta.innerHTML = value || '';
        return ta.value;
    };

    const storedSize = wrapper => {
        const md = decode(wrapper?.dataset?.md || '');
        const m = md.match(/\{\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*\}\s*$/);
        if (!m) return null;
        const width = Number(m[1]), height = Number(m[2]);
        return width > 0 && height > 0 ? { width, height, md } : null;
    };

    const renderDiv = () => document.getElementById('task-desc-render');
    const maxVisibleWidth = wrapper => {
        const render = renderDiv();
        if (!render) return null;
        const rr = render.getBoundingClientRect();
        const wr = wrapper.getBoundingClientRect();
        return Math.max(1, rr.left + render.clientWidth - wr.left);
    };

    const sync = wrapper => {
        if (!wrapper || wrapper.classList.contains('is-resizing')) return;
        const saved = storedSize(wrapper);
        const maxWidth = maxVisibleWidth(wrapper);
        if (!saved || maxWidth == null) return;
        const width = Math.min(saved.width, maxWidth);
        const height = width < saved.width ? Math.max(1, width * saved.height / saved.width) : saved.height;
        wrapper.style.width = `${width}px`;
        wrapper.style.height = `${height}px`;
    };

    const syncAll = () => document.querySelectorAll('.image-resizer-wrapper.has-custom-size').forEach(sync);

    const mutationObserver = new MutationObserver(mutations => {
        for (const mutation of mutations) {
            for (const node of mutation.addedNodes) {
                if (node.nodeType === 1) {
                    if (node.matches?.('.image-resizer-wrapper.has-custom-size')) sync(node);
                    node.querySelectorAll?.('.image-resizer-wrapper.has-custom-size').forEach(sync);
                }
            }
        }
    });
    mutationObserver.observe(document.documentElement, { childList: true, subtree: true });

    const installObservers = () => {
        const render = renderDiv();
        if (!render || render.__doeResizeObserved) return;
        render.__doeResizeObserved = true;
        if (typeof ResizeObserver !== 'undefined') {
            const ro = new ResizeObserver(syncAll);
            ro.observe(render);
            render.__doeResizeObserver = ro;
        }
        window.addEventListener('resize', syncAll, { passive: true });
        syncAll();
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', installObservers, { once: true });
    } else {
        installObservers();
    }

    const ensureDescriptionRoom = (descWrapper, imageWrapper, baseHeight) => {
        if (!descWrapper) return;
        const dr = descWrapper.getBoundingClientRect();
        const ir = imageWrapper.getBoundingClientRect();
        const required = Math.max(baseHeight || 0, ir.bottom - dr.top + 18);
        if (required > dr.height + 0.5) descWrapper.style.height = `${required}px`;
    };

    document.addEventListener('mousedown', event => {
        if (event.button !== 0) return;
        const handle = event.target.closest?.('.image-resize-handle');
        if (!handle) return;

        const wrapper = handle.closest('.image-resizer-wrapper');
        const render = renderDiv();
        const descWrapper = document.querySelector('.description-wrapper');
        if (!wrapper || !render) return;

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();

        const saved = storedSize(wrapper);
        const rect = wrapper.getBoundingClientRect();
        const startX = event.clientX;
        const startY = event.clientY;
        const startWidth = rect.width;
        const startHeight = rect.height;
        const savedWidth = saved?.width || startWidth;
        const savedHeight = saved?.height || startHeight;
        const ratio = savedWidth / Math.max(1, savedHeight);
        const hadExplicitHeight = !!(descWrapper && descWrapper.style.height.trim());
        const baseHeight = hadExplicitHeight ? (parseFloat(descWrapper.style.height) || descWrapper.getBoundingClientRect().height) : null;

        let desiredWidth = startWidth;
        let desiredHeight = startHeight;
        const minSize = 50;
        wrapper.classList.add('is-resizing', 'has-custom-size');
        document.body.style.userSelect = 'none';

        let finished = false;
        const onMove = e => {
            if (finished) return;
            desiredWidth = Math.max(minSize, startWidth + (e.clientX - startX));
            if (e.shiftKey) {
                desiredHeight = Math.max(minSize, startHeight + (e.clientY - startY));
            } else {
                desiredHeight = Math.max(minSize, desiredWidth / ratio);
            }

            const maxWidth = maxVisibleWidth(wrapper) ?? desiredWidth;
            const visibleWidth = Math.min(desiredWidth, maxWidth);
            const visibleHeight = visibleWidth < desiredWidth
                ? Math.max(1, visibleWidth * desiredHeight / desiredWidth)
                : desiredHeight;

            wrapper.style.width = `${visibleWidth}px`;
            wrapper.style.height = `${visibleHeight}px`;
            ensureDescriptionRoom(descWrapper, wrapper, baseHeight);
        };

        const onUp = async () => {
            if (finished) return;
            finished = true;
            window.removeEventListener('blur', onUp);
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            document.body.style.userSelect = '';

            const finalWidth = Math.round(desiredWidth);
            const finalHeight = Math.round(desiredHeight);
            const originalMd = decode(wrapper.dataset.md || '');
            const match = originalMd.match(/!\[([^\]]*)\]\(([^)]+)\)(?:\{[^}]+\})?/);
            const newMd = match ? originalMd.replace(match[0], `![${match[1]}](${match[2]}){${finalWidth}, ${finalHeight}}`) : originalMd;

            try {
                if (typeof cmEditor !== 'undefined' && cmEditor && newMd !== originalMd) {
                    const text = cmEditor.getValue();
                    const sameWrappers = Array.from(render.querySelectorAll('.image-resizer-wrapper'))
                        .filter(w => decode(w.dataset.md || '') === originalMd);
                    const occurrence = sameWrappers.indexOf(wrapper);
                    let idx = -1;
                    let searchFrom = 0;
                    const occurrenceTarget = occurrence >= 0 ? occurrence : 0;
                    for (let i = 0; i <= occurrenceTarget; i++) {
                        idx = text.indexOf(originalMd, searchFrom);
                        if (idx === -1) break;
                        searchFrom = idx + originalMd.length;
                    }
                    if (idx !== -1) {
                        const from = cmEditor.posFromIndex(idx);
                        const to = cmEditor.posFromIndex(idx + originalMd.length);
                        cmEditor.replaceRange(newMd, from, to);
                        wrapper.dataset.md = typeof escapeHtml === 'function' ? escapeHtml(newMd) : newMd;
                        if (typeof lastSavedValue !== 'undefined') lastSavedValue = cmEditor.getValue();
                        const taskModal = document.getElementById('task-modal');
                        const taskId = taskModal?.dataset.taskId;
                        if (taskId && typeof updateTask === 'function') await updateTask(taskId, { description: cmEditor.getValue() });
                        if (typeof bumpModalUpdatedDate === 'function') bumpModalUpdatedDate();
                    }
                }
            } catch (err) {
                console.error('[Image resize] save failed', err);
            }

            if (descWrapper) {
                if (hadExplicitHeight) {
                    const dr = descWrapper.getBoundingClientRect();
                    const ir = wrapper.getBoundingClientRect();
                    const required = ir.bottom - dr.top + 18;
                    descWrapper.style.height = `${Math.max(baseHeight || 0, required)}px`;
                    if (required <= (baseHeight || 0) + 0.5) descWrapper.style.height = `${baseHeight}px`;
                } else {
                    descWrapper.style.height = '';
                }
            }

            wrapper.classList.remove('is-resizing');
            wrapper.dataset.justResized = '1';
            setTimeout(() => delete wrapper.dataset.justResized, 300);
            sync(wrapper);
        };

        window.addEventListener('blur', onUp, { once: true });
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp, { once: true });
        onMove(event);
    }, true);
})();
